@namespace sv_4b6283692095420a93852b28ee075f43.Components.Pages.Apply

<div class="step-content">
    @if (IsSubmitted)
    {
        <div class="text-center py-5">
            <div class="mb-3">
                <span style="font-size: 3rem; color: #198754;">&#10003;</span>
            </div>
            <h4 class="text-success">Application Submitted Successfully!</h4>
            <p class="text-muted">Your application ID is: <strong>@ApplicationId</strong></p>
        </div>
    }
    else
    {
        <h4 class="mb-4">Review & Submit</h4>

        @if (!string.IsNullOrEmpty(ErrorMessage))
        {
            <div class="alert alert-danger">@ErrorMessage</div>
        }

        <!-- Personal Info -->
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Personal Information</strong>
                <button class="btn btn-link btn-sm" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <div class="card-body">
                @if (Personal is not null)
                {
                    <div class="row">
                        <div class="col-md-6"><strong>Name:</strong> @Personal.FullName</div>
                        <div class="col-md-6"><strong>Email:</strong> @Personal.Email</div>
                        <div class="col-md-6"><strong>Phone:</strong> @Personal.Phone</div>
                        <div class="col-md-6"><strong>Address:</strong> @Personal.Address</div>
                    </div>
                }
            </div>
        </div>

        <!-- Work History -->
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Work History</strong>
                <button class="btn btn-link btn-sm" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            <div class="card-body">
                @if (WorkEntries is not null)
                {
                    @foreach (var entry in WorkEntries)
                    {
                        <div class="mb-2 pb-2 border-bottom">
                            <strong>@entry.Title</strong> at @entry.Company<br />
                            <small class="text-muted">
                                @entry.StartDate.ToString("MMM yyyy") &ndash;
                                @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                            </small>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="mb-0 mt-1">@entry.Description</p>
                            }
                        </div>
                    }
                }
            </div>
        </div>

        <!-- References -->
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>References</strong>
                <button class="btn btn-link btn-sm" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            <div class="card-body">
                @if (References is not null)
                {
                    @foreach (var r in References)
                    {
                        <div class="mb-2">
                            <strong>@r.Name</strong> (@r.Relationship) &mdash; @r.Email
                            @if (!string.IsNullOrWhiteSpace(r.Phone))
                            {
                                <span>, @r.Phone</span>
                            }
                        </div>
                    }
                }
            </div>
        </div>

        <!-- Cover Letter -->
        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Cover Letter</strong>
                <button class="btn btn-link btn-sm" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <div class="card-body">
                <p style="white-space: pre-wrap;">@CoverLetter</p>
            </div>
        </div>

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="OnBack">Back</button>
            <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@IsSubmitting">
                @if (IsSubmitting)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Submit Application
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfo? Personal { get; set; }
    [Parameter] public List<WorkEntry>? WorkEntries { get; set; }
    [Parameter] public List<Reference>? References { get; set; }
    [Parameter] public string? CoverLetter { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }

    public bool IsSubmitted { get; set; }
    public int ApplicationId { get; set; }
    public bool IsSubmitting { get; set; }
    public string ErrorMessage { get; set; } = string.Empty;

    private async Task HandleSubmit()
    {
        ErrorMessage = string.Empty;
        IsSubmitting = true;
        StateHasChanged();

        await OnSubmit.InvokeAsync();
    }

    public void SetSubmitted(int applicationId)
    {
        IsSubmitted = true;
        ApplicationId = applicationId;
        IsSubmitting = false;
        StateHasChanged();
    }

    public void SetError(string message)
    {
        ErrorMessage = message;
        IsSubmitting = false;
        StateHasChanged();
    }
}

