@namespace sv_4b6283692095420a93852b28ee075f43.Components.Pages.Apply

<div class="step-content">
    <h4 class="mb-4">Cover Letter</h4>

    <div class="mb-3">
        <label class="form-label">Write your cover letter</label>
        <textarea class="form-control" rows="12" maxlength="@MaxLength"
                  value="@CoverLetterText"
                  @oninput="HandleInput"></textarea>
        <div class="form-text text-end">
            @CoverLetterText.Length / @MaxLength characters
        </div>
    </div>

    <div class="d-flex justify-content-between">
        <button class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string? Data { get; set; }
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string CoverLetterText { get; set; } = string.Empty;
    private const int MaxLength = 2000;

    protected override void OnParametersSet()
    {
        if (Data is not null)
        {
            CoverLetterText = Data;
        }
    }

    private void HandleInput(ChangeEventArgs e)
    {
        var value = (string?)e.Value ?? string.Empty;
        CoverLetterText = value.Length > MaxLength ? value[..MaxLength] : value;
    }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync(CoverLetterText);
    }
}

