<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="@currentStep"
                   StepNames="@stepNames"
                   OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Data="@personalInfo"
                              OnNext="HandlePersonalNext"
                              ValidateEmail="ApplicationService.ValidateEmailAsync" />
            break;
        case 1:
            <WorkHistoryStep Data="@workEntries"
                             OnNext="HandleWorkNext"
                             OnBack="GoBack" />
            break;
        case 2:
            <ReferencesStep Data="@references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;
        case 3:
            <CoverLetterStep Data="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;
        case 4:
            <ReviewStep @ref="reviewStepRef"
                        Personal="@personalInfo"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnEditStep="GoToStep"
                        OnBack="GoBack"
                        OnSubmit="HandleSubmit" />
            break;
    }
</div>

@code {
    private int currentStep = 0;
    private ReviewStep? reviewStepRef;

    private readonly List<string> stepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private PersonalInfo? personalInfo;
    private List<WorkEntry>? workEntries;
    private List<Reference>? references;
    private string? coverLetter;

    private void HandlePersonalNext(PersonalInfo info)
    {
        personalInfo = info;
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkEntry> entries)
    {
        workEntries = entries;
        currentStep = 2;
    }

    private void HandleReferencesNext(List<Reference> refs)
    {
        references = refs;
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        currentStep = 4;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void GoToStep(int step)
    {
        if (step < currentStep)
            currentStep = step;
    }

    private async Task HandleSubmit()
    {
        try
        {
            var application = new JobApplication(
                personalInfo!,
                new WorkHistory(workEntries!),
                references!,
                coverLetter ?? string.Empty
            );

            var id = await ApplicationService.SubmitApplicationAsync(application);
            reviewStepRef?.SetSubmitted(id);
        }
        catch (Exception ex)
        {
            reviewStepRef?.SetError($"Submission failed: {ex.Message}");
        }
    }
}

